import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/officeDocument/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

def read_shared_strings(z):
    try:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    except KeyError:
        return []
    out = []
    for si in root.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}t"))
        out.append(text)
    return out

def read_sheet(z, path, shared):
    root = ET.fromstring(z.read(path))
    rows = []
    for row in root.findall("m:sheetData/m:row", NS):
        cells = {}
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            val = v.text if v is not None else None
            if t == "s" and val is not None:
                val = shared[int(val)]
            elif val is not None:
                try:
                    val = float(val)
                    if val.is_integer():
                        val = int(val)
                except ValueError:
                    pass
            if val is not None:
                cells[col_to_idx(ref)] = val
        if cells:
            rows.append(cells)
    return rows

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    shared = read_shared_strings(z)
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = []
    for s in wb_root.findall("m:sheets/m:sheet", NS):
        sheets.append((s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")))
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {}
    for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
        rels[rel.get("Id")] = rel.get("Target")

    for name, rid in sheets:
        target = rels[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        print(f"--- Sheet: {name} ---")
        rows = read_sheet(z, target, shared)
        for i, cells in enumerate(rows, start=1):
            print(f"row {i}: {cells}")

